ALTER TABLE wiki_receipts ADD COLUMN project_id TEXT;
UPDATE wiki_receipts SET project_id=(SELECT project_id FROM wiki_pages WHERE workspace_id=wiki_receipts.workspace_id AND id=result_id);
ALTER TABLE wiki_events ADD COLUMN project_id TEXT;
UPDATE wiki_events SET project_id=(SELECT project_id FROM wiki_pages WHERE workspace_id=wiki_events.workspace_id AND id=aggregate_id);
CREATE TABLE wiki_frozen_scopes (workspace_id TEXT NOT NULL, project_id TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('frozen','purging','purged')), PRIMARY KEY(workspace_id,project_id));
CREATE TABLE wiki_purge_bypass (workspace_id TEXT NOT NULL, project_id TEXT NOT NULL, PRIMARY KEY(workspace_id,project_id));
CREATE TRIGGER wiki_freeze_revisions_insert BEFORE INSERT ON wiki_revisions WHEN EXISTS(SELECT 1 FROM wiki_frozen_scopes f WHERE f.workspace_id=NEW.workspace_id AND (f.project_id='' OR f.project_id=(SELECT project_id FROM wiki_pages WHERE workspace_id=NEW.workspace_id AND id=NEW.page_id))) AND NOT EXISTS(SELECT 1 FROM wiki_purge_bypass b WHERE b.workspace_id=NEW.workspace_id AND (b.project_id='' OR b.project_id=(SELECT project_id FROM wiki_pages WHERE workspace_id=NEW.workspace_id AND id=NEW.page_id))) BEGIN SELECT RAISE(ABORT,'scope frozen'); END;
CREATE TRIGGER wiki_freeze_revisions_update BEFORE UPDATE ON wiki_revisions WHEN (EXISTS(SELECT 1 FROM wiki_frozen_scopes f WHERE f.workspace_id=NEW.workspace_id AND (f.project_id='' OR f.project_id=(SELECT project_id FROM wiki_pages WHERE workspace_id=NEW.workspace_id AND id=NEW.page_id))) AND NOT EXISTS(SELECT 1 FROM wiki_purge_bypass b WHERE b.workspace_id=NEW.workspace_id AND (b.project_id='' OR b.project_id=(SELECT project_id FROM wiki_pages WHERE workspace_id=NEW.workspace_id AND id=NEW.page_id)))) OR (EXISTS(SELECT 1 FROM wiki_frozen_scopes f WHERE f.workspace_id=OLD.workspace_id AND (f.project_id='' OR f.project_id=(SELECT project_id FROM wiki_pages WHERE workspace_id=OLD.workspace_id AND id=OLD.page_id))) AND NOT EXISTS(SELECT 1 FROM wiki_purge_bypass b WHERE b.workspace_id=OLD.workspace_id AND (b.project_id='' OR b.project_id=(SELECT project_id FROM wiki_pages WHERE workspace_id=OLD.workspace_id AND id=OLD.page_id)))) BEGIN SELECT RAISE(ABORT,'scope frozen'); END;
CREATE TRIGGER wiki_freeze_revisions_delete BEFORE DELETE ON wiki_revisions WHEN EXISTS(SELECT 1 FROM wiki_frozen_scopes f WHERE f.workspace_id=OLD.workspace_id AND (f.project_id='' OR f.project_id=(SELECT project_id FROM wiki_pages WHERE workspace_id=OLD.workspace_id AND id=OLD.page_id))) AND NOT EXISTS(SELECT 1 FROM wiki_purge_bypass b WHERE b.workspace_id=OLD.workspace_id AND (b.project_id='' OR b.project_id=(SELECT project_id FROM wiki_pages WHERE workspace_id=OLD.workspace_id AND id=OLD.page_id))) BEGIN SELECT RAISE(ABORT,'scope frozen'); END;
CREATE TRIGGER wiki_freeze_receipts_insert BEFORE INSERT ON wiki_receipts WHEN EXISTS(SELECT 1 FROM wiki_frozen_scopes f WHERE f.workspace_id=NEW.workspace_id AND (f.project_id='' OR f.project_id=NEW.project_id)) AND NOT EXISTS(SELECT 1 FROM wiki_purge_bypass b WHERE b.workspace_id=NEW.workspace_id AND (b.project_id='' OR b.project_id=NEW.project_id)) BEGIN SELECT RAISE(ABORT,'scope frozen'); END;
